import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.DqMqoJl9.js";const p=JSON.parse('{"title":"AI skills","description":"","frontmatter":{"title":"AI skills"},"headers":[],"relativePath":"skills/index.md","filePath":"skills/index.md"}'),n={name:"skills/index.md"};function r(o,e,d,h,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="ai-skills" tabindex="-1">AI skills <a class="header-anchor" href="#ai-skills" aria-label="Permalink to &quot;AI skills&quot;">​</a></h1><p><code>paystack_sdk</code> ships skills for AI coding agents (Claude Code <code>SKILL.md</code> folders) that teach an agent how to use the gem correctly: the conventions, what raises and what returns, and the checks that keep money safe. They are installed from the gem you have, so they match its version.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paystack_sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # any Ruby project: into ./.claude/skills</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin/rails</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paystack_sdk:skills</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # a Rails app</span></span></code></pre></div><p>Installing is safe to repeat. It only touches folders it installed (each carries a <code>.paystack_sdk.json</code> marker), never overwrites a skill of yours, and stamps each <code>SKILL.md</code> with the gem version. Run it again after upgrading the gem.</p><h2 id="the-skills" tabindex="-1">The skills <a class="header-anchor" href="#the-skills" aria-label="Permalink to &quot;The skills&quot;">​</a></h2><p>An agent picks a skill from its description, so each one starts with <em>Use when...</em>.</p><table tabindex="0"><thead><tr><th>Skill</th><th>Load it when</th></tr></thead><tbody><tr><td><a href="/skills/paystack-sdk-overview.html"><code>paystack-sdk-overview</code></a></td><td>Use when writing or reviewing Ruby code that calls Paystack through the paystack_sdk gem: creating a client, picking a resource and method, reading a Response, handling errors, or deciding how far to trust a result. Load this first; it covers the conventions every other paystack-sdk skill assumes.</td></tr><tr><td><a href="/skills/paystack-sdk-charge-statuses.html"><code>paystack-sdk-charge-statuses</code></a></td><td>Use when code starts a payment with the Charge API (card or mobile money) and must react to what comes back: a status such as send_pin, send_otp, send_phone, pay_offline, pending, failed or success, deciding what to show the payer, and which paystack_sdk call to make next. Also use when a charge call reports success? but the payment did not go through.</td></tr><tr><td><a href="/skills/paystack-sdk-mobile-money.html"><code>paystack-sdk-mobile-money</code></a></td><td>Use when charging a mobile money wallet in Ghana (MTN, Telecel, AT Money/AirtelTigo) with paystack_sdk, or any provider that uses charges.mobile_money: choosing the provider code and the phone number format, what the payer sees, how long the payer has, how to learn the result, and what test mode does not prove.</td></tr><tr><td><a href="/skills/paystack-sdk-money-safety.html"><code>paystack-sdk-money-safety</code></a></td><td>Use before writing, reviewing or merging any code that moves or records money with the paystack_sdk gem: starting or confirming a payment, granting value after a webhook or return URL, charging a saved card, handling a timeout on a write, storing card or authorization data, logging or reporting errors that touch a Paystack client, choosing keys per environment, or reconciling payments. A checklist of rules, each checked against the gem and the Paystack test API, ending in a pre-merge table.</td></tr><tr><td><a href="/skills/paystack-sdk-payments.html"><code>paystack-sdk-payments</code></a></td><td>Use when building or reviewing the hosted checkout flow with paystack_sdk: starting a payment with client.transactions.initiate, redirecting the payer to authorization_url, handling the callback_url return, confirming with transactions.verify and paid?, reading a verify status such as success, abandoned or failed, making confirmation safe when the callback and the webhook arrive together, deciding which transaction fields to store, or looking transactions up with fetch and list.</td></tr><tr><td><a href="/skills/paystack-sdk-refunds.html"><code>paystack-sdk-refunds</code></a></td><td>Use when code returns money to a customer for a Paystack payment with paystack_sdk (client.refunds): a full or partial refund, checking how much of a transaction is already refunded, reading a refund status (pending, processing, processed, failed, needs-attention), handling refund webhooks, recovering from a timeout on a refund request, or showing the payer what happened. Load it before writing any code that calls refunds.create.</td></tr><tr><td><a href="/skills/paystack-sdk-saved-card-renewals.html"><code>paystack-sdk-saved-card-renewals</code></a></td><td>Use when charging a returning customer saved card without checkout through paystack_sdk: renewals, dues or instalments your own app schedules, saving the reusable authorization from a first payment, calling transactions.charge_authorization or partial_debit, designing renewal references, handling a declined, rejected or timed-out renewal, dunning, or a lost authorization code. Not for Paystack Plans or Subscriptions.</td></tr><tr><td><a href="/skills/paystack-sdk-testing.html"><code>paystack-sdk-testing</code></a></td><td>Use when writing or running tests for an app that calls Paystack through the paystack_sdk gem: choosing keys for test, staging and CI, stubbing Paystack HTTP with WebMock (success, 400, 401, 429, 500 and timeout bodies), writing an opt-in test-API suite, using Paystacks published test cards and test mobile money number, testing a webhook endpoint, or deciding what test mode can never prove.</td></tr><tr><td><a href="/skills/paystack-sdk-webhooks.html"><code>paystack-sdk-webhooks</code></a></td><td>Use when building or reviewing the endpoint that receives Paystack webhooks (charge.success, refund.<em>, transfer.</em>, subscription.<em>, invoice.</em>, dispute.*) in a Rails or Rack app: verifying the x-paystack-signature header with PaystackSdk::Webhook, reading the raw request body, skipping CSRF, answering 200 fast and working in a background job, handling duplicate or out-of-order deliveries, and testing the endpoint with a signed request. Also use when checking whether Paystack delivered a webhook, or replaying one, with client.webhook_events.</td></tr></tbody></table><h2 id="for-agents-that-cannot-install-a-gem" tabindex="-1">For agents that cannot install a gem <a class="header-anchor" href="#for-agents-that-cannot-install-a-gem" aria-label="Permalink to &quot;For agents that cannot install a gem&quot;">​</a></h2><p>Every skill is also published as raw markdown at <code>/skills/&lt;name&gt;.md</code>, with an index at <code>/skills/index.md</code>, and the whole site is summarised in <a href="/llms.txt"><code>/llms.txt</code></a>. Fetch the one that matches the task.</p>`,9)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
